@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
:root{--acid:#c6d15a;--acid2:#e1e794;--ink:#111613;--muted:#a0a59a;--line:rgba(222,227,205,.18);--mono:'IBM Plex Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#111713;color:#eef0e5;font-family:var(--mono)}button,input,select{font:inherit}button{color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#171d19}#renderCanvas{width:100%;height:100%;display:block;outline:none;touch-action:none}.film-grain{pointer-events:none;position:absolute;inset:0;z-index:3;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.hidden{display:none!important}.screen{position:absolute;inset:0;z-index:5;background:linear-gradient(90deg,rgba(10,15,12,.94) 0%,rgba(10,15,12,.83) 37%,rgba(10,15,12,.22) 72%,rgba(10,15,12,.12) 100%),linear-gradient(0deg,rgba(8,12,10,.72),transparent 30%,transparent 80%,rgba(8,12,10,.34);display:flex;flex-direction:column;justify-content:space-between;padding:32px 5.2vw 22px}.menu-top,.menu-footer{display:flex;align-items:center;justify-content:space-between}.logo{display:flex;align-items:center;gap:12px;font:800 21px var(--display);letter-spacing:1.6px}.logo b{color:var(--acid)}.logo small{display:block;color:#9da398;font:10px var(--mono);letter-spacing:2px;margin-top:3px}.logo-symbol,.footer-mark{display:grid;place-items:center;width:39px;height:39px;border:1px solid var(--acid);color:var(--acid);font:800 23px var(--display);clip-path:polygon(0 0,100% 0,100% 72%,68% 100%,0 100%)}.menu-top-right{display:flex;align-items:center;gap:25px;font-size:10px;letter-spacing:1px;color:#a6afa2}.online-dot,.live-dot{display:inline-block;width:6px;height:6px;border-