or:var(--acid)}.mode-card span b{display:block;font:600 10px var(--mono);letter-spacing:.4px}.mode-card span small{display:block;color:#92998c;font-size:9px;margin-top:5px}.mode-card u{text-decoration:none;position:absolute;right:9px;top:8px;color:transparent;font-size:10px}.mode-card.selected u{color:var(--acid)}.menu-footer{border-top:1px solid rgba(220,225,209,.17);padding-top:13px;font-size:8px;letter-spacing:1px;color:#879083}.menu-footer>div{display:flex;align-items:center;gap:9px}.menu-footer .footer-mark{width:20px;height:20px;font-size:12px}.menu-footer i{font-style:normal;color:#596154}.menu-footer>div:nth-child(2){gap:17px}.menu-footer>div:last-child{font-size:9px}.menu-footer b{color:var(--acid)}.menu-side-note{position:absolute;right:26px;top:48%;writing-mode:vertical-rl;font-size:8px;letter-spacing:2px;color:#b2b89e66}.pause-screen{justify-content:center;align-items:center;background:rgba(7,11,9,.78);backdrop-filter:blur(8px)}.pause-card{width:min(440px,90vw);border-left:2px solid var(--acid);padding:16px 35px;background:linear-gradient(120deg,rgba(28,36,29,.94),rgba(17,22,18,.84));box-shadow:0 20px 70px #0008}.pause-card h2,.settings-card h2{font:800 50px var(--display);margin:14px 0 4px;letter-spacing:1px}.pause-card p{color:#a6ad9e;font-size:11px;margin:0 0 24px}.pause-card button{width:100%;margin:7px 0}.pause-card .secondary-button{justify-content:center}.text-button{height:38px;border:0;background:none;color:#aab09f;cursor:pointer;font-size:10px;letter-spacing:1px}.text-button:hover{color:var(--acid)}.pause-hint{margin-top:20px;color:#747d70;font-size:8px;letter-spacing:1px;text-align:center}.pause-hint span{color:var(--acid);padding:0 5px}.settings-modal{position:absolute;inset:0;z-index:12;display:grid;place-items:center;background:#050806b8;backdrop-filter:blur(8px)}.settings-card{width:min(420px,90vw);position:relative;padding:32px;background:#171e18;border:1px solid #68704f;box-shadow:0 20px 80px #000}.settings-card h2{font-size:40px;margin-bottom:30px}.modal-close{position:absolute;right:18px;top:15px;width:30px;height:30px;background:none;border:1px solid var(--line);font-size:22px;cursor:pointer}.settings-card label{display:grid;grid-template-columns:1fr auto;gap:10px;color:#b0b7a7;font-size:10px;letter-spacing:1px;margin:20px 0}.settings-card label b{color:var(--acid)}.settings-card input,.settings-card select{grid-column:span 2;width:100%;accent-color:var(--acid)}.settings-card select{background:#222a22;color:#e7ebdc;border:1px solid #465043;padding:8px}.setting-note{border-top:1px solid var(--line);padding-top:15px;color:#788173;font-size:9px;line-height:1.7}.loading{position:absolute;z-index:20;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#101612;color:var(--acid);gap:10px;transition:opacity .5s}.loading-mark{font:800 58px var(--display);border:1px solid var(--acid);width:80px;height:80px;display:grid;place-items:center;clip-path:polygon(0 0,100% 0,100% 72%,68% 100%,0 100%)}.loading b{font:600 12px var(--mono);letter-spacing:2px;margin-top:12px}.loading small{font:9px var(--mono);letter-spacing:1px;color:#858d7c}.loading i{width:175px;height:2px;background:#353f30;position:relative;margin:6px}.loading i:after{content:'';position:absolute;inset:0;background:var(--acid);transform-origin:left;animation:load 1.4s ease-in-out infinite}@keyframes load{from{transform:scaleX(.08)}to{transform:scaleX(1)}}.fatal{position:absolute;inset:0;z-index:30;background:#111713;display:grid;place-items:center;padding:30px;color:#e6e9dc;text-align:center}
/* in-game HUD */.hud{position:absolute;inset:0;z-index:4;pointer-events:none;color:#f2f1e7}.topline{position:absolute;top:0;left:0;right:0;height:68px;display:flex;align-items:center;justify-content:space-between;padding:0 25px;background:linear-gradient(180deg,#0b100fdb,#11171300)}.brand-mark{display:flex;align-items:center;gap:9px;font:600 11px var(--mono);letter-spacing:1.4px}.brand-icon{width:27px;height:27px;border:1px solid var(--acid);color:var(--acid);display:grid;place-items:center;font:700 16px var(--display)}.brand-mark small{display:block;color:#8f988d;font:8px var(--mono);letter-spacing:1px;margin-top:4px}.round-info{display:flex;align-items:center;gap:15px;font-size:9px;color:#a9b0a1;letter-spacing:1px}.round-info>strong{font:700 20px var(--display);color:#eff1e5}.round-score{border-left:1px solid var(--line);padding-left:14px}.round-score i{font-style:normal;font-size:8px;color:#899185}.round-score b{color:var(--acid);font-size:13px;padding:0 4px}.round-score em{font-style:normal;color:#596254}.objective{font-size:9px;letter-spacing:1px;color:#a3ab9c}.objective b{display:block;color:var(--acid);font-weight:500;margin:5px 0 0 15px}.radar-panel{position:absolute;right:24px;top:79px;width:168px;background:#101713b8;border:1px solid #737a5d52;padding:8px 9px 7px}.radar-title{font-size:8px;letter-spacing:.8px;color:#a9b19e;display:flex;justify-content:space-between}.radar-title b{color:var(--acid);font-size:7px}.radar-panel canvas{width:148px;height:148px;display:block;margin:6px auto 2px}.radar-foot{display:flex;justify-content:space-around;font-size:7px;color:#8e9788}.radar-foot span:first-child{color:#a6cb7e}.radar-foot span:last-child{color:#e77b62}.crosshair{position:absolute;top:50%;left:50%;width:30px;height:30px;transform:translate(-50%,-50%);display:flex;align-items:center;justify-content:center;transition:width .1s,height .1s}.crosshair i{position:absolute;background:#e8ebd3;box-shadow:0 0 2px #111;width:2px;height:7px}.crosshair i:nth-child(1){top:0}.crosshair i:nth-child(2){bottom:0}.crosshair i:nth-child(3){left:0;width:7px;height:2px}.crosshair i:nth-child(4){right:0;width:7px;height:2px}.crosshair b{width:2px;height:2px;border-radius:50%;background:var(--acid)}.hit-marker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.6);font:700 24px var(--mono);color:#e9e9d8;opacity:0;text-shadow:0 0 5px #000;transition:.1s}.hit-marker.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.mission-toast{position:absolute;left:50%;top:18%;transform:translate(-50%,-10px);opacity:0;background:#111713c9;border-left:2px solid var(--acid);padding:9px 16px;transition:.3s;text-align:center}.mission-toast.show{opacity:1;transform:translate(-50%,0)}.mission-toast span{display:block;font-size:8px;letter-spacing:1.4px;color:var(--acid)}.mission-toast b{font-size:10px;font-weight:500;display:block;margin-top:5px}.bottom-left{position:absolute;left:25px;bottom:22px;width:210px;padding:13px 15px;background:linear-gradient(90deg,#101713d9,#10171380);border-left:2px solid var(--acid)}.status-row{display:grid;grid-template-columns:23px 42px 1fr;align-items:center;gap:7px;margin:4px 0 9px}.status-icon{font-size:17px;color:var(--acid);text-align:center}.status-row small{display:block;color:#9da598;font-size:7px;letter-spacing:1px}.status-row b{font:600 20px var(--display);line-height:1.1}.meter{height:3px;background:#50574a}.meter i{height:100%;display:block;background:var(--acid);width:100%;transition:width .3s}.armor-row .status-icon{color:#9ba9b2}.armor-row .meter i{background:#9ba9b2}.cash-line{border-top:1px solid #ffffff1a;padding-top:8px;color:#949b8e;font-size:7px;letter-spacing:.5px}.cash-line b{float:right;color:#e0e5d6;font-size:10px}.bottom-center{position:absolute;left:50%;bottom:28px;transform:translateX(-50%);display:flex;gap:12px;align-items:center;color:#aab1a1}.stance-icon{color:var(--acid);font-size:16px}.key-hint{font-size:8px;color:#e5e8db}.key-hint span{color:#878f82;margin-left:4px;font-size:7px}.bottom-right{position:absolute;right:25px;bottom:22px;text-align:right;min-width:190px;padding:8px 13px;background:linear-gradient(270deg,#101713e3,#10171366);border-right:2px solid var(--acid)}.weapon-label span{display:block;font-size:7px;letter-spacing:1.2px;color:#9da598}.weapon-label b{font:700 27px var(--display);letter-spacing:1px}.ammo{display:flex;align-items:baseline;justify-content:flex-end;gap:6px;margin-top:-3px}.ammo strong{font:700 28px var(--display)}.ammo span{font-size:14px;color:#737b70}.ammo b{font:500 15px var(--display);color:#a2aa9b}.ammo-caption{font-size:7px;letter-spacing:1px;color:#949c8d}.ammo-caption span{color:var(--acid);margin-left:8px}.weapon-slots{display:flex;justify-content:flex-end;gap:5px;margin-top:8px}.weapon-slots span{border:1px solid #ffffff2a;color:#91998c;padding:3px 6px;font-size:8px}.weapon-slots span.active{border-color:var(--acid);color:var(--acid)}.weapon-slots b{font-weight:500}.damage-vignette{position:absolute;inset:0;box-shadow:inset 0 0 0 rgba(180,35,20,0);transition:box-shadow .3s}.damage-vignette.hit{box-shadow:inset 0 0 110px rgba(180,35,20,.62)}.killfeed{position:absolute;top:125px;right:210px;text-align:right;font-size:9px;letter-spacing:.4px}.killfeed div{background:#111713b8;margin:3px;padding:7px 9px;color:#cdd2c3;animation:feed 4s forwards}.killfeed b{color:var(--acid)}@keyframes feed{0%,75%{opacity:1}100%{opacity:0}}.reload-indicator{position:absolute;left:50%;bottom:16%;transform:translateX(-50%);font-size:9px;letter-spacing:1.5px;color:var(--acid)}.reload-indicator span{display:block;width:120px;height:2px;background:#69714e;margin-top:7px;overflow:hidden}.reload-indicator span:after{content:'';display:block;height:100%;background:var(--acid);animation:reload 1.6s linear forwards}@keyframes reload{from{width:0}to{width:100%}}.touch-controls{display:none}.fatal{font-family:var(--mono)}
@media(max-width:760px){.screen{padding:20px 6vw 15px;background:linear-gradient(90deg,#0a0f0eed 0%,#0a0f0ec9 65%,#0a0f0e70 100%),linear-gradient(0deg,#080c0ae8,transparent 35%)}.menu-center{margin:0;width:min(500px,90vw);padding-bottom:0}.menu-center h1{font-size:clamp(62px,14vw,90px);margin:16px 0}.menu-copy{font-size:10px}.menu-top-right>span{display:none}.menu-footer>div:nth-child(2){display:none}.menu-footer>div:last-child{font-size:7px}.menu-side-note{display:none}.mode-switch{margin-top:20px}.topline{padding:0 12px;height:55px}.brand-mark{font-size:9px}.objective{display:none}.round-info{gap:7px}.round-info>span:first-child{display:none}.round-score{padding-left:7px}.radar-panel{right:10px;top:61px;width:121px;padding:6px}.radar-panel canvas{width:105px;height:105px}.radar-title{font-size:7px}.radar-foot{font-size:6px}.bottom-left{left:10px;bottom:13px;width:150px;padding:8px}.status-row{grid-template-columns:17px 32px 1fr;gap:4px;margin:2px 0 6px}.status-row b{font-size:16px}.cash-line{font-size:6px}.bottom-right{right:10px;bottom:13px;min-width:130px;padding:6px}.weapon-label b{font-size:21px}.ammo strong{font-size:23px}.bottom-center{display:none}.killfeed{right:140px;top:90px}.mission-toast{top:22%}.touch-controls{display:flex;position:absolute;inset:auto 0 0;height:180px;justify-content:space-between;align-items:flex-end;padding:0 20px 18px;pointer-events:auto}.touch-move button,.touch-actions button{background:#111a14a8;border:1px solid #bec77b77;color:#dce1cb;border-radius:50%;width:43px;height:43px}.touch-move>div{display:flex;gap:4px;margin-top:4px}.touch-move>button{margin-left:47px}.touch-actions{display:flex;align-items:end;gap:8px}.touch-actions button{width:52px;height:52px}.touch-actions #touch-fire{background:#bd4a3980;border-color:#e2866c;font-size:10px}.bottom-left,.bottom-right{bottom:193px}.menu-actions{gap:6px}.primary-button,.secondary-button{padding:0 10px;gap:8px;font-size:9px;min-width:0;height:43px}.primary-button{flex:1}.secondary-button{flex:1}.mode-card{height:52px;padding:6px}.mode-card span b{font-size:8px}.mode-card span small{font-size:7px}.logo{font-size:17px}.loading-mark{width:64px;height:64px;font-size:45px}}
@media(max-height:650px){.menu-center{transform:scale(.88);transform-origin:left center}.menu-center h1{margin:12px 0}.mode-switch{margin-top:16px}.menu-footer{font-size:7px}.bottom-left,.bottom-right{bottom:10px}.bottom-center{bottom:14px}}

(() => {
  'use strict';
  const canvas = document.getElementById('renderCanvas');
  const $ = id => document.getElementById(id);
  const engine = new BABYLON.Engine(canvas, true, {preserveDrawingBuffer:false, stencil:true, antialias:true, powerPreference:'high-performance'});
  engine.setHardwareScalingLevel(Math.min(1.35, window.devicePixelRatio || 1));
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(.36,.40,.37,1);
  scene.fogMode = BABYLON.Scene.FOGMODE_EXP2; scene.fogDensity=.0038; scene.fogColor=new BABYLON.Color3(.36,.40,.37);
  scene.collisionsEnabled=true; scene.gravity=new BABYLON.Vector3(0,-.28,0);
  const camera = new BABYLON.UniversalCamera('operator', new BABYLON.Vector3(0,1.8,-51), scene);
  camera.attachControl(canvas,true); camera.minZ=.08; camera.fov=80*Math.PI/180; camera.speed=.32; camera.angularSensibility=3100;
  camera.checkCollisions=true; camera.applyGravity=true; camera.ellipsoid=new BABYLON.Vector3(.38,.88,.38); camera.ellipsoidOffset=new BABYLON.Vector3(0,.02,0); camera.inertia=.72;
  const hemi=new BABYLON.HemisphericLight('overcast',new BABYLON.Vector3(.15,1,-.2),scene); hemi.intensity=.82; hemi.groundColor=new BABYLON.Color3(.18,.2,.17);
  const sun=new BABYLON.DirectionalLight('late sun',new BABYLON.Vector3(-.5,-1,.38),scene); sun.position=new BABYLON.Vector3(35,55,-25); sun.intensity=1.15;
  const shadow=new BABYLON.ShadowGenerator(512,sun); shadow.useBlurExponentialShadowMap=true; shadow.blurKernel=12; shadow.setDarkness(.3);
  const mat=(name,color,rough=.8,emissive=null)=>{const m=new BABYLON.StandardMaterial(name,scene);m.diffuseColor=BABYLON.Color3.FromHexString(color);m.specularColor=new BABYLON.Color3(.14,.14,.12);m.specularPower=(1-rough)*60;if(emissive)m.emissiveColor=BABYLON.Color3.FromHexString(emissive);return m;};
  const M={ground:mat('worn concrete','#65685e'),wall:mat('weathered concrete','#777a70'),wallDark:mat('interior shadow','#424941'),steel:mat('aged steel','#59615b'),steel2:mat('painted olive','#555e4c'),rust:mat('oxidized metal','#765342'),yellow:mat('safety ochre','#b19a4d'),wood:mat('timber','#685b49'),crate:mat('crate paint','#59604c'),glass:mat('dirty glass','#56605a'),black:mat('gunmetal','#252b28'),gun:mat('weapon steel','#303734'),tire:mat('rubber','#202522'),target:mat('target orange','#bd5a39'),targetDark:mat('target dark','#704a38'),enemy:mat('hostile uniform','#6f4939'),enemyVest:mat('hostile webbing','#a05d3e'),ally:mat('operator uniform','#34433a'),allyVest:mat('operator vest','#4b5845'),skin:mat('skin','#a58b6f'),lamp:mat('warning light','#d1b65a',.4,'#62512a')};
  const meshes=[], obstacles=[], actors=[], targets=[], botList=[], decor=[];
  let started=false,mode='training',weapon='rifle',health=100,armor=100,cash=800,score=0,blueScore=0,redScore=0,roundSeconds=240,paused=false,reloading=false,fireHeld=false,lastShot=0,shotCount=0,moveAmount=0,grounded=false,stance='standing',isRunning=false,slowWalk=false,alive=true,toastTimer=0,fireRate=105,sensitivity=1,quality='high',roundOver=false;
  const keys=Object.create(null), V=(x,y,z)=>new BABYLON.Vector3(x,y,z), rand=(a,b)=>a+Math.random()*(b-a);
  function box(name,x,y,z,w,h,d,material,collide=true){const b=BABYLON.MeshBuilder.CreateBox(name,{width:w,height:h,depth:d},scene);b.position.set(x,y,z);b.material=material;b.checkCollisions=collide;b.receiveShadows=true;if(collide)obstacles.push({x,z,rx:w/2,rz:d/2});meshes.push(b);return b;}
  function cyl(name,x,y,z,diam,height,material,tess=12){const c=BABYLON.MeshBuilder.CreateCylinder(name,{diameter:diam,height,tessellation:tess},scene);c.position.set(x,y,z);c.material=material;c.receiveShadows=true;shadow.addShadowCaster(c);meshes.push(c);return c;}
  function beam(name,a,b,width,material){const delta=b.subtract(a), length=delta.length();const c=BABYLON.MeshBuilder.CreateCylinder(name,{height:length,diameter:width,tessellation:8},scene);c.position=a.add(b).scale(.5);c.rotationQuaternion=BABYLON.Quaternion.FromUnitVectorsToRef?BABYLON.Quaternion.FromUnitVectorsToRef(BABYLON.Axis.Y,delta.normalize(),new BABYLON.Quaternion()):null;if(!c.rotationQuaternion){c.lookAt(b);c.rotate(BABYLON.Axis.X,Math.PI/2);}c.material=material;c.receiveShadows=true;shadow.addShadowCaster(c);meshes.push(c);return c;}
  function makeSign(text,x,y,z,rot=0){const p=BABYLON.MeshBuilder.CreatePlane('stencilled signage',{width:4.2,height:1.05},scene);p.position.set(x,y,z);p.rotation.y=rot;const tex=new BABYLON.DynamicTexture('sign paint',{width:512,height:128},scene,false);tex.hasAlpha=true;const c=tex.getContext();c.fillStyle='#252b26';c.fillRect(0,0,512,128);c.fillStyle='#c2ca9c';c.font='bold 48px monospace';c.fillText(text,20,78);c.fillStyle='#c0a556';c.fillRect(20,96,472,4);tex.update();const m=new BABYLON.StandardMaterial('stencilled panel',scene);m.diffuseTexture=tex;m.emissiveColor=new BABYLON.Color3(.15,.16,.12);p.material=m;p.isPickable=false;return p;}
  function createWorld(){
    const floor=BABYLON.MeshBuilder.CreateGround('scuffed concrete yard',{width:150,height:150,subdivisions:2},scene);floor.position.y=0;floor.material=M.ground;floor.checkCollisions=true;floor.receiveShadows=true;meshes.push(floor);
    // Perimeter wall, loading bays, roofless industrial sheds.
